begin;
create function pg_temp.expect(value boolean,description text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',description;end if;end$$;
create function pg_temp.rejects(statement text) returns boolean language plpgsql as $$begin execute statement;return false;exception when others then return true;end$$;
grant execute on function pg_temp.expect(boolean,text),pg_temp.rejects(text) to authenticated;

-- Review proof uses the real confirmed payment and protected ledger created by
-- this contract. Only the synthetic booking's clock/fulfillment receipt is moved
-- into the past; these rows, ratings and moderator decisions are rolled back.
create function pg_temp.exercise_experience_review(aid uuid,bid uuid,h uuid,c uuid,s uuid,hs uuid,cs uuid,ss uuid,hid text,sid text) returns void language plpgsql as $$
declare r public.worker_booking_reviews;receipt uuid;old_stamp timestamptz;result jsonb;
begin
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'session_id',ss,'role','authenticated')::text,true);
 perform pg_temp.expect(not (public.get_my_experience_review(bid)->>'eligible')::boolean,'paid future session does not earn a review');
 perform pg_temp.expect(pg_temp.rejects(format('select public.submit_my_experience_review(%L,5,%L)',bid,'Before attending')),'payment alone cannot submit a review');
 alter table public.experience_bookings disable trigger guard_experience_booking_contract;
 update public.experience_bookings set contract=contract||jsonb_build_object('starts_at',now()-interval '3 hours','ends_at',now()-interval '2 hours'),
  attendance_confirmed_at=now()-interval '3 hours',host_finished_at=now()-interval '2 hours',customer_completed_at=now()-interval '1 hour',status='completed' where id=bid;
 alter table public.experience_bookings enable trigger guard_experience_booking_contract;
 perform pg_temp.expect((public.get_my_experience_review(bid)->>'eligible')::boolean,'paid confirmed attendance and completion earns a review');
 r:=public.submit_my_experience_review(bid,4,'Useful orientation with clear instructions.');old_stamp:=r.updated_at;
 perform pg_temp.expect(public.submit_my_experience_review(bid,4,'Useful orientation with clear instructions.')=r,'uncertain submission retries reuse the same review');
 r:=public.submit_my_experience_review(bid,5,'Updated after considering the full activity.',old_stamp);
 perform pg_temp.expect(pg_temp.rejects(format('select public.submit_my_experience_review(%L,3,%L,%L)',bid,'Stale competing edit',old_stamp)),'stale review edit rejected');
 perform pg_temp.expect((public.get_public_experience_reviews(aid)->'summary'->>'count')::integer=1,'public activity summary includes one earned review');
 perform pg_temp.expect(exists(select 1 from public.get_public_worker_reviews(hid,20) where id=r.id),'same Provider profile includes activity reviews');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_my_experience_review(%L)',bid)),'host cannot impersonate the reviewing customer');
 receipt:=public.report_content('provider_review','untrusted-client-subject','inappropriate','Please check this activity review.',r.id::text);
 perform pg_temp.expect(public.report_provider_review(r.id,'inappropriate','Uncertain response retry')=receipt,'reported review has one tracked receipt');
 perform pg_temp.expect(pg_temp.rejects(format('select public.moderate_provider_review(%L,true,%L,%L,%L)',receipt,'Host cannot hide a review',r.updated_at,gen_random_uuid())),'reviewed Provider cannot remove customer feedback');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'session_id',cs,'role','authenticated','aal','aal2')::text,true);
 perform pg_temp.expect(public.get_provider_review_moderation(receipt)->'snapshot'->>'comment'='Updated after considering the full activity.','moderator sees reported evidence');
 perform pg_temp.expect(pg_temp.rejects(format('select public.admin_resolve_content_report(%L,%L,%L)',receipt,'actioned','False removal receipt')),'generic report closure cannot pretend review removal');
 result:=public.moderate_provider_review(receipt,true,'Contains information requiring a privacy review.',r.updated_at,gen_random_uuid());
 perform pg_temp.expect(result->'review'->>'hidden_at' is not null,'atomic moderation hides review');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'session_id',ss,'role','authenticated')::text,true);
 perform pg_temp.expect((public.get_public_experience_reviews(aid)->'summary'->>'count')::integer=0,'hidden feedback removed from activity score');
 perform pg_temp.expect(exists(select 1 from public.notifications where recipient_id=sid and source_id=bid::text and destination_route='experience_booking' and type='provider_review_moderation'),'reviewer decision reaches exact booking');
 r:=public.submit_my_experience_review(bid,5,'Edited review remains under moderation.',(result->'review'->>'updated_at')::timestamptz);
 perform pg_temp.expect(r.hidden_at is not null,'editing cannot restore hidden content');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'session_id',cs,'role','authenticated','aal','aal2')::text,true);
 result:=public.moderate_provider_review(receipt,false,'Reviewed the corrected feedback and restored visibility.',r.updated_at,gen_random_uuid());
 perform pg_temp.expect(result->'review'->>'hidden_at' is null,'independent moderator can restore retained review');
end $$;

-- Invoked inside the independently approved fixture below; the surrounding
-- transaction rolls every policy, publication and hold back afterward.
create function pg_temp.exercise_experience_publication(aid uuid,session_id uuid,h uuid,c uuid,s uuid,hs uuid,cs uuid,ss uuid,hid text,cid text,sid text) returns void language plpgsql as $$
declare eg uuid;ep integer;pub jsonb;q jsonb;held jsonb;bid uuid:=gen_random_uuid();other_id uuid:=gen_random_uuid();before_contract jsonb;
 checkout jsonb;paid_checkout jsonb;confirmation jsonb;protection uuid;action_id uuid;refund_booking uuid;refund_reference text;review_updated timestamptz;
begin
 update public.creator_elevation_grants set action_classes=array['private_evidence','policy_publish'] where creator_user_id=cid returning creator_elevation_id into eg;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'session_id',cs,'role','authenticated')::text,true);
 ep:=coalesce((public.creator_get_experience_commission()->'policy'->>'version')::integer,0);
 perform public.creator_publish_experience_commission(eg,ep,10,'Disposable publication and booking contract; rolled back.');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
 pub:=public.get_my_experience_publication(aid);
 perform pg_temp.expect((pub->>'can_publish')::boolean and not (pub->>'published')::boolean,'approval is distinct from host publication');
 pub:=public.set_my_experience_publication(aid,3,0,true);
 perform pg_temp.expect((pub->>'visible')::boolean and (pub->>'revision')::integer=1,'host explicitly publishes the approved revision');
 perform pg_temp.expect(public.set_my_experience_publication(aid,3,0,true)=pub,'lost publish response returns the same publication');
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_booking_quote(%L,1)',session_id)),'host cannot book their own session');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'session_id',ss,'role','authenticated')::text,true);
 perform pg_temp.expect(pg_temp.rejects(format('select public.set_my_experience_publication(%L,3,1,false)',aid)),'another provider cannot unpublish the host activity');
 perform pg_temp.expect(exists(select 1 from jsonb_array_elements(public.search_experiences('NG','orientation Lafia')->'items') x where x->>'id'=aid::text),'customer discovery matches approved title and area');
 perform pg_temp.expect(not exists(select 1 from jsonb_array_elements(public.search_experiences('NG','','','Lagos')->'items') x where x->>'id'=aid::text),'location filter excludes this activity in a different state');
 perform pg_temp.expect(public.get_published_experience(aid)->'details' ? 'what_to_expect','public detail includes the actual activity');
 -- A restriction on Services covers its activities too, without erasing approval.
 insert into private.workspace_restrictions(user_id,workspace,restricted,public_reason)
 values(hid,'worker',true,'Services conduct is under review');
 perform pg_temp.expect(not exists(select 1 from jsonb_array_elements(public.search_experiences('NG','orientation Lafia')->'items') x where x->>'id'=aid::text),'restricted Services cannot keep selling an activity through another catalog');
 perform pg_temp.expect(public.get_published_experience(aid) is null,'restricted activity detail is unavailable');
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_booking_quote(%L,1)',session_id)),'restricted activity cannot quote a new booking');
 perform pg_temp.expect(exists(select 1 from public.experience_activities where id=aid and status='approved'),'restriction preserves independent activity approval');
 update private.workspace_restrictions set restricted=false,version=gen_random_uuid() where user_id=hid and workspace='worker';
 perform pg_temp.expect(exists(select 1 from jsonb_array_elements(public.search_experiences('NG','orientation Lafia')->'items') x where x->>'id'=aid::text),'restoring Services reuses valid activity approval');

 perform pg_temp.expect(not (public.get_published_experience(aid) ? 'approval_note'),'internal review notes are not public detail');
 perform pg_temp.expect(jsonb_array_length(public.get_published_experience_sessions(aid))>=1,'customer can select approved dated sessions');
 q:=public.get_experience_booking_quote(session_id,8);
 perform pg_temp.expect((q->'contract'->>'total_minor')::bigint=2000000 and q->'contract'->>'customer_cancellation_before_deadline'='full_refund','server quote calculates participants and agreed refund rule');
 held:=public.hold_experience_booking(bid,session_id,8,q->>'contract_hash');before_contract:=held->'contract';
 perform pg_temp.expect(held->>'status'='pending_payment' and held->>'payment_id' is null,'capacity hold never manufactures payment');
 perform pg_temp.expect(public.hold_experience_booking(bid,session_id,8,q->>'contract_hash')=held,'retry cannot reserve capacity twice');
 checkout:=public.create_experience_checkout(bid);
 perform pg_temp.expect(public.create_experience_checkout(bid)=checkout,'checkout retry returns one canonical payment reference');
 perform pg_temp.expect(pg_temp.rejects(format('select public.hold_experience_booking(%L,%L,1,%L)',bid,session_id,q->>'contract_hash')),'idempotency key is bound to exact participant count');
 q:=public.get_experience_booking_quote(session_id,1);
 perform pg_temp.expect((q->>'remaining')::integer=0,'held participants exhaust the actual session capacity');
 perform pg_temp.expect(pg_temp.rejects(format('select public.hold_experience_booking(%L,%L,1,%L)',other_id,session_id,q->>'contract_hash')),'oversell is rejected rather than acknowledging another hold');
 execute 'set local role authenticated';
 perform pg_temp.expect(pg_temp.rejects('select * from public.experience_bookings'),'browser cannot bypass the booking projection');
 perform pg_temp.expect(pg_temp.rejects('select * from public.experience_publications'),'browser cannot mutate publication tables directly');
 execute 'reset role';
 update public.experience_bookings set expires_at=now()-interval '1 second' where id=bid;
 perform pg_temp.expect(pg_temp.rejects(format('select public.create_experience_checkout(%L)',bid)),'expired checkout cannot initialize another charge');
 held:=public.hold_experience_booking(other_id,session_id,1,q->>'contract_hash');
 perform pg_temp.expect(held->>'status'='pending_payment','expired unpaid hold releases capacity');
 paid_checkout:=public.create_experience_checkout(other_id);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'session_id',cs,'role','authenticated')::text,true);
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_my_experience_booking(%L)',bid)),'unrelated account cannot read private customer booking');
 perform public.creator_publish_experience_commission(eg,ep+1,20,'Changed commission for new quotes only; rolled back.');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'session_id',ss,'role','authenticated')::text,true);
 perform pg_temp.expect(public.get_my_experience_booking(bid)->'contract'=before_contract,'accepted booking snapshot survives later commission changes');
 perform pg_temp.expect(pg_temp.rejects(format('select public.hold_experience_booking(%L,%L,1,%L)',gen_random_uuid(),session_id,q->>'contract_hash')),'stale commission quote cannot be accepted');
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 confirmation:=public.process_verified_paystack_charge('charge.success:'||(checkout->>'reference'),'charge.success',checkout->>'reference',repeat('e',64),now(),2000000,'NGN','test-expired-charge');
 perform pg_temp.expect(confirmation->>'success'='false','late verified charge cannot reclaim expired session capacity');
 perform pg_temp.expect(exists(select 1 from public.verified_provider_events where provider_reference=checkout->>'reference' and processing_status='failed'),'late verified charge remains durable for Finance reconciliation');
 confirmation:=public.process_verified_paystack_charge('charge.success:'||(paid_checkout->>'reference'),'charge.success',paid_checkout->>'reference',repeat('f',64),now(),250000,'NGN','test-current-charge');
 perform pg_temp.expect(confirmation->>'success'='true','canonical gateway confirms the valid Experience charge: '||confirmation::text);
 select payment_protection_id into protection from public.experience_bookings where id=other_id;
 perform pg_temp.expect(exists(select 1 from public.payment_protection_transactions where id=protection and protection_state='protected' and amount_total=2500 and amount_commission=250 and amount_payee=2250 and protected_ledger_transaction_id is not null),'original accepted commission enters the canonical protected ledger');
 confirmation:=public.process_verified_paystack_charge('charge.success:'||(paid_checkout->>'reference'),'charge.success',paid_checkout->>'reference',repeat('f',64),now(),250000,'NGN','test-current-charge');
 perform pg_temp.expect((confirmation->>'already_processed')::boolean,'provider receipt retry cannot duplicate payment');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'session_id',ss,'role','authenticated')::text,true);
 perform pg_temp.expect(pg_temp.rejects(format('select public.progress_experience_booking(%L,%L)',other_id,'attend')),'customer cannot report attendance before the accepted session starts');
 perform pg_temp.expect(pg_temp.rejects(format('select public.progress_experience_booking(%L,%L)',other_id,'complete')),'customer cannot release funds before attendance and completion');
 perform pg_temp.expect(public.get_my_payment_receipts(paid_checkout->>'reference')->0->>'booking_type'='experience','shared receipt identifies the actual Experience');
 perform pg_temp.expect((public.get_my_payment_receipts(paid_checkout->>'reference')->0->>'participants')::integer=1,'shared receipt retains the booked participant count');
 perform pg_temp.exercise_experience_review(aid,other_id,h,c,s,hs,cs,ss,hid,sid);
 -- Exercise the shared release processor with a service-authorized fixture action.
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 perform public.transition_payment_protection(protection,'release_eligible','contract_release_authorized','experience-release-authorized:'||protection,null,'contract_fixture',null,null,'{}');
 insert into public.financial_action_outbox(action_type,subject_type,subject_id,payment_protection_id,amount,idempotency_key,status)
 values('release_experience_payment','experience_booking',other_id::text,protection,2500,'experience-contract-release:'||protection,'processing') returning financial_action_id into action_id;
 confirmation:=public.complete_internal_release_action(action_id);
 perform pg_temp.expect(confirmation->>'success'='true','Experience net earnings release through the existing outbox');
 perform pg_temp.expect(exists(select 1 from public.wallets where owner_id=hid and owner_type='worker' and available_balance=2250),'Experience earnings use the existing Provider wallet');
 perform pg_temp.expect(not exists(select 1 from public.property_partner_earning_releases where payment_id=(paid_checkout->>'payment_id')::uuid),'Experience release does not manufacture property earnings');
 perform pg_temp.expect(exists(select 1 from public.booking_payments where id=(paid_checkout->>'payment_id')::uuid and amount_commission=250 and net_amount=2250),'release preserves accepted Experience commission and net');
 confirmation:=public.complete_internal_release_action(action_id);
 perform pg_temp.expect((confirmation->>'already_completed')::boolean,'Experience release retry credits the wallet once');
 -- Both customer deadline cancellation and host cancellation return the full
 -- accepted charge through the real shared refund processor, never wallet credit.
 for ep in 1..2 loop
  perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'session_id',ss,'role','authenticated')::text,true);
  refund_booking:=gen_random_uuid();q:=public.get_experience_booking_quote(session_id,1);
  perform public.hold_experience_booking(refund_booking,session_id,1,q->>'contract_hash');
  checkout:=public.create_experience_checkout(refund_booking);refund_reference:='experience-refund-'||refund_booking;
  perform set_config('request.jwt.claims','{"role":"service_role"}',true);
  confirmation:=public.process_verified_paystack_charge('charge.success:'||(checkout->>'reference'),'charge.success',checkout->>'reference',repeat('b',64),now(),250000,'NGN','test-refund-charge');
  perform pg_temp.expect(confirmation->>'success'='true','refundable Experience charge confirmed: '||confirmation::text);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',case when ep=1 then s else h end,'session_id',case when ep=1 then ss else hs end,'role','authenticated')::text,true);
  held:=public.cancel_experience_booking(refund_booking,'Disposable agreed cancellation contract');
  perform pg_temp.expect(held->>'status'='refund_pending','cancellation queues refund without claiming provider completion');
  perform public.cancel_experience_booking(refund_booking,'Disposable agreed cancellation contract');
  perform pg_temp.expect((select count(*)=1 from public.financial_action_outbox where idempotency_key='experience-cancel-refund:'||refund_booking),'cancel retry creates one refund');
  select financial_action_id,payment_protection_id into action_id,protection from public.financial_action_outbox where idempotency_key='experience-cancel-refund:'||refund_booking;
  perform set_config('request.jwt.claims','{"role":"service_role"}',true);
  update public.financial_action_outbox set status='processing',attempt_count=1 where financial_action_id=action_id;
  perform public.record_refund_provider_submission(action_id,refund_reference,'pending',repeat('c',64));
  confirmation:=public.process_verified_paystack_refund_event('refund.processed:'||refund_reference,'refund.processed',checkout->>'reference',refund_reference,refund_reference,repeat('d',64),now(),250000,'NGN');
  perform pg_temp.expect(exists(select 1 from public.payment_protection_transactions where id=protection and refunded_amount=2500 and released_amount=0),'customer receives full original amount without a host release');
  perform pg_temp.expect(exists(select 1 from public.experience_bookings where id=refund_booking and status='cancelled'),'provider refund completion reaches actual booking');
  perform public.process_verified_paystack_refund_event('refund.processed:'||refund_reference,'refund.processed',checkout->>'reference',refund_reference,refund_reference,repeat('d',64),now(),250000,'NGN');
  perform pg_temp.expect(exists(select 1 from public.wallets where owner_id=hid and owner_type='worker' and available_balance=2250),'refund and provider retry do not credit the host again');
 end loop;
 -- A real customer issue retains capacity and needs independent elevated review.
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'session_id',ss,'role','authenticated')::text,true);
 refund_booking:=gen_random_uuid();q:=public.get_experience_booking_quote(session_id,1);
 perform public.hold_experience_booking(refund_booking,session_id,1,q->>'contract_hash');
 checkout:=public.create_experience_checkout(refund_booking);
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 confirmation:=public.process_verified_paystack_charge('charge.success:'||(checkout->>'reference'),'charge.success',checkout->>'reference',repeat('a',64),now(),250000,'NGN','test-reviewed-charge');
 perform pg_temp.expect(confirmation->>'success'='true','reviewed booking starts with a genuine confirmed payment');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'session_id',ss,'role','authenticated')::text,true);
 held:=public.request_experience_booking_review(refund_booking,'payment_issue','Please review this charged activity payment');
 perform pg_temp.expect(held->>'status'='review_pending','customer issue reaches real review case');
 perform pg_temp.expect((public.get_experience_booking_quote(session_id,1)->>'remaining')::integer=6,'reviewed booking retains its accepted capacity');
 perform pg_temp.expect(pg_temp.rejects(format('select public.decide_experience_booking_review(%L,now(),50,%L,%L)',refund_booking,'Customer cannot decide own financial issue',eg)),'customer cannot authorize a financial decision');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'session_id',cs,'role','authenticated')::text,true);
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_finance_reviews(%L)',eg)),'policy elevation does not authorize Finance review');
 update public.creator_elevation_grants set action_classes=array['finance_exception'] where creator_elevation_id=eg;
 held:=public.get_experience_finance_reviews(eg,null,null,refund_booking)->0;
 perform pg_temp.expect(held->>'id'=refund_booking::text,'Creator can open the exact review outside the current page');
 review_updated:=(held->>'updated_at')::timestamptz;
 held:=public.decide_experience_booking_review(refund_booking,review_updated,50,'Reviewed the actual agreed payment and evidence',eg);
 perform public.decide_experience_booking_review(refund_booking,review_updated,50,'Reviewed the actual agreed payment and evidence',eg);
 perform pg_temp.expect((select count(*)=2 from public.financial_action_outbox where subject_id=refund_booking::text),'financial decision retry creates exactly one refund and one release');
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 select financial_action_id,payment_protection_id into action_id,protection from public.financial_action_outbox where subject_id=refund_booking::text and action_type='release_experience_payment';
 update public.financial_action_outbox set status='processing',attempt_count=1 where financial_action_id=action_id;
 confirmation:=public.complete_internal_release_action(action_id);
 perform pg_temp.expect((confirmation->>'commission')::numeric=250 and (confirmation->>'payee_amount')::numeric=1000,'accepted 20 percent applies to retained 1250, not the original 2500');
 select financial_action_id into action_id from public.financial_action_outbox where subject_id=refund_booking::text and action_type='refund_experience_booking';
 update public.financial_action_outbox set status='processing',attempt_count=1 where financial_action_id=action_id;
 refund_reference:='experience-reviewed-refund-'||refund_booking;
 perform public.record_refund_provider_submission(action_id,refund_reference,'pending',repeat('c',64));
 perform public.process_verified_paystack_refund_event('refund.processed:'||refund_reference,'refund.processed',checkout->>'reference',refund_reference,refund_reference,repeat('d',64),now(),125000,'NGN');
 perform pg_temp.expect(exists(select 1 from public.payment_protection_transactions where id=protection and released_amount=1250 and refunded_amount=1250 and commission_recognized_amount=250),'partial decision settles exactly the protected gross');
 perform pg_temp.expect(exists(select 1 from public.wallets where owner_id=hid and owner_type='worker' and available_balance=3250),'partial decision credits only the retained net');
 update public.creator_elevation_grants set action_classes=array['private_evidence','policy_publish'] where creator_elevation_id=eg;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
 pub:=public.set_my_experience_publication(aid,3,1,false);
 perform pg_temp.expect(not (pub->>'visible')::boolean and public.get_published_experience(aid) is null,'unpublish removes the customer projection');
 perform pg_temp.expect(public.get_my_experience_booking(bid)->'contract'=before_contract,'unpublish preserves customer and host booking history');
end $$;
do $$
declare h uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); s uuid:=gen_random_uuid();
 hs uuid:=gen_random_uuid(); cs uuid:=gen_random_uuid(); ss uuid:=gen_random_uuid();
 hid text:='experience-check-'||h; cid text:='experience-check-'||c; sid text:='experience-check-'||s;
 aid uuid:=gen_random_uuid(); review_session uuid:=gen_random_uuid(); photo_id uuid:=gen_random_uuid(); rev integer; receipt jsonb;
 body jsonb:='{"title":"Campus orientation walk","category":"culture_tours","what_to_expect":"We walk through the local campus area and explain the history, meeting places and practical orientation information.","host_expertise":"I have led orientation walks locally and can explain the planned route and its landmarks.","country_code":"NG","state":"Nasarawa","local_area":"Lafia","city":"Lafia","meeting_area":"Agreed public meeting point","timezone":"Africa/Lagos","participation_requirements":"Adults able to walk this route; comfortable shoes required.","accessibility_information":"Step-free route; contact the host for assistance arrangements.","duration_minutes":60,"max_group_size":8,"inclusions":["Guided walk"],"exclusions":["Transport"]}';
begin
 insert into auth.users(id,aud,role,email,created_at,updated_at) values
 (h,'authenticated','authenticated',h||'@example.invalid',now(),now()),(c,'authenticated','authenticated',c||'@example.invalid',now(),now()),(s,'authenticated','authenticated',s||'@example.invalid',now(),now());
 insert into public.profiles(auth_id,email,user_id,role,profile_complete,full_name,state,city) values
 (h,h||'@example.invalid',hid,'user',true,'Application host','Nasarawa','Lafia'),(c,c||'@example.invalid',cid,'user',true,'Application reviewer','Nasarawa','Lafia'),(s,s||'@example.invalid',sid,'user',true,'Other applicant','Nasarawa','Lafia');
 insert into auth.sessions(id,user_id,created_at,updated_at) values(hs,h,now(),now()),(cs,c,now(),now()),(ss,s,now(),now());
 insert into public.user_sessions(user_id,auth_id,auth_session_id,device_id,device,is_active,trust_status) values
 (hid,h,hs,'check-'||h,'Browser',true,'trusted'),(cid,c,cs,'check-'||c,'Browser',true,'trusted'),(sid,s,ss,'check-'||s,'Browser',true,'trusted');
 insert into public.workspace_role_assignments(user_id,workspace_role,scope_type) values(hid,'worker','global'),(cid,'creator','global'),(sid,'worker','global');
 insert into public.creator_elevation_grants(creator_user_id,auth_user_id,auth_session_id,action_classes,expires_at,verification_method) values(cid,c,cs::text,array['private_evidence'],now()+interval '5 minutes','password');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
 receipt:=public.save_my_experience_activity(aid,0,body);
