 declare session_id uuid:=gen_random_uuid(); first_receipt jsonb; future_start timestamptz:=now()+interval '10 days';
 begin
  execute 'set local role authenticated';
  first_receipt:=public.save_my_experience_session(aid,session_id,0,1,future_start,8,250000,'NGN');
  perform pg_temp.expect(first_receipt->>'status'='draft' and (first_receipt->>'revision')::integer=1,'prepared session stays private');
  perform pg_temp.expect(public.save_my_experience_session(aid,session_id,0,1,future_start,8,250000,'NGN')=first_receipt,'lost session save response is idempotent');
  perform pg_temp.expect(jsonb_array_length(public.get_my_experience_sessions(aid))=1,'host can list prepared dates');
  perform pg_temp.expect(pg_temp.rejects('select * from public.experience_sessions'),'browser cannot bypass session RPC authority');
  perform pg_temp.expect(pg_temp.rejects(format('select public.save_my_experience_session(%L,%L,1,1,%L,9,250000,%L)',aid,session_id,future_start,'NGN')),'session capacity cannot exceed activity maximum');
  perform pg_temp.expect(pg_temp.rejects(format('select public.save_my_experience_session(%L,%L,1,1,%L,8,250000,%L)',aid,session_id,future_start,'USD')),'currency must match activity country');
  perform pg_temp.expect(pg_temp.rejects(format('select public.save_my_experience_session(%L,%L,1,0,%L,8,250000,%L)',aid,session_id,future_start,'NGN')),'stale activity revision cannot prepare dates');
  perform pg_temp.expect(pg_temp.rejects(format('select public.save_my_experience_session(%L,%L,1,1,%L,8,250000,%L)',aid,session_id,now()-interval '1 day','NGN')),'new past date rejected');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'session_id',ss,'role','authenticated')::text,true);
  perform pg_temp.expect(pg_temp.rejects(format('select public.get_my_experience_sessions(%L)',aid)),'other provider cannot read prepared dates');
  perform pg_temp.expect(pg_temp.rejects(format('select public.archive_my_experience_session(%L,%L,1)',aid,session_id)),'other provider cannot archive dates');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
  first_receipt:=public.save_my_experience_session(aid,session_id,1,1,future_start,7,300000,'NGN');
  perform pg_temp.expect((first_receipt->>'revision')::integer=2,'session edit increments revision');
  perform pg_temp.expect(pg_temp.rejects(format('select public.save_my_experience_session(%L,%L,1,1,%L,6,300000,%L)',aid,session_id,future_start,'NGN')),'conflicting stale edit rejected');
  first_receipt:=public.archive_my_experience_session(aid,session_id,2);
  perform pg_temp.expect(public.archive_my_experience_session(aid,session_id,2)=first_receipt,'archive retry is idempotent');
  perform pg_temp.expect(jsonb_array_length(public.get_my_experience_sessions(aid))=0,'archived date leaves active preparation list');
  perform pg_temp.expect(pg_temp.rejects(format('select public.save_my_experience_session(%L,%L,3,1,%L,7,300000,%L)',aid,session_id,future_start,'NGN')),'archived date cannot be reactivated');
  execute 'reset role';
  perform pg_temp.expect((select count(*)=3 from public.experience_session_events where experience_session_events.session_id=(first_receipt->>'id')::uuid),'three mutations retain exactly three audit snapshots');
 end;

