 declare evidence jsonb; document_id uuid; object_name text; key uuid:=gen_random_uuid();
 begin
  evidence:=public.get_experience_evidence_review(aid);
  perform pg_temp.expect(not (evidence->>'configured')::boolean and not (evidence->>'ready')::boolean,'unconfigured evidence never approves an activity');
  perform public.configure_experience_evidence_requirements(aid,0,'[{"code":"venue_permission","label":"Venue permission","instructions":"Provide permission for the proposed activity at this venue.","requires_expiry":true}]','Review the actual venue permission and its valid dates for this activity.');
  perform pg_temp.expect(exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=aid::text and e.event_type='experience.evidence.required' and a.recipient_user_id=hid and a.workspace='worker'),'requirements reach host Activity');
  perform pg_temp.expect(pg_temp.rejects(format('select public.configure_experience_evidence_requirements(%L,0,%L,%L)',aid,'[]','A stale requirements change must fail.')),'stale requirements revision rejected');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
  evidence:=public.begin_experience_evidence_upload(aid,'venue_permission',key,'application/pdf',9,'permission.pdf');
  document_id:=(evidence->>'id')::uuid;object_name:=evidence->>'object_path';
  perform pg_temp.expect(public.begin_experience_evidence_upload(aid,'venue_permission',key,'application/pdf',9,'permission.pdf')=evidence,'upload reservation retry preserves exact version');
  perform pg_temp.expect(pg_temp.rejects(format('select public.finish_experience_evidence_upload(%L)',document_id)),'missing storage object cannot become submitted evidence');
  perform public.reserve_my_media_upload('experience-evidence',object_name);
  insert into storage.objects(bucket_id,name,metadata,version) values('experience-evidence',object_name,'{"size":9,"mimetype":"application/pdf"}',gen_random_uuid()::text);
  evidence:=public.finish_experience_evidence_upload(document_id);
  perform pg_temp.expect(exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=document_id::text and e.event_type='experience.evidence.submitted' and a.recipient_user_id=cid and a.workspace='creator' and a.action_required and a.resolved_at is null),'evidence reaches independent Creator review');
  perform pg_temp.expect(evidence->>'status'='submitted','confirmed storage metadata permits submission');
  perform pg_temp.expect(pg_temp.rejects(format('select public.review_experience_evidence(%L,%L,%L,now()+interval ''1 day'')',document_id,'approved','Host must not self-approve.')),'host self-review rejected');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'session_id',ss,'role','authenticated')::text,true);
  perform pg_temp.expect(not public.can_access_experience_evidence_object(object_name),'unrelated provider cannot read private evidence');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'session_id',cs,'role','authenticated')::text,true);
  perform pg_temp.expect(pg_temp.rejects(format('select public.review_experience_evidence(%L,%L,%L)',document_id,'approved','Expiry must be confirmed.')),'required expiry cannot be omitted');
  perform public.review_experience_evidence(document_id,'approved','Venue permission reviewed for the proposed activity.',now()+interval '1 day');
  perform pg_temp.expect(not exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=document_id::text and e.event_type='experience.evidence.submitted' and a.resolved_at is null),'review resolves submission actions');
  perform pg_temp.expect((public.get_experience_evidence_review(aid)->>'ready')::boolean,'current independently approved evidence becomes ready');
 end;
 -- Exercise approval against the same prepared application in a subtransaction,
 -- then roll back only this branch so correction/withdrawal tests remain valid.
 begin
  receipt:=public.get_experience_approval_readiness(aid,2);
  perform pg_temp.expect(not (receipt->>'can_approve')::boolean and not (receipt->'checks'->>'identity')::boolean,'missing current account identity blocks activity approval');
  perform pg_temp.expect(pg_temp.rejects(format('select public.approve_experience_activity(%L,2,%L)',aid,'Activity evidence, photos and dated sessions reviewed.')),'approval cannot bypass missing identity');
  -- Synthetic passed identity is fixture setup, not a live provider verification.
  insert into public.worker_identity_checks(worker_id,account_role,status,captured_at,consent_at,attempt_count,challenge_result)
   values(hid,'worker','passed',now(),now(),1,'{"contract_fixture":true}');
  receipt:=public.get_experience_approval_readiness(aid,2);
  perform pg_temp.expect((receipt->>'can_approve')::boolean,'all required checks produce approval readiness');
  -- Later market or data changes cannot keep an obsolete session approvable.
  update public.experience_sessions set currency='USD' where activity_id=aid;
  perform pg_temp.expect(not (public.get_experience_approval_readiness(aid,2)->'checks'->>'sessions')::boolean,'stale country currency blocks session readiness');
  perform pg_temp.expect(pg_temp.rejects(format('select public.approve_experience_activity(%L,2,%L)',aid,'Activity evidence, photos and dated sessions reviewed.')),'approval rechecks current currency on the server');
  update public.experience_sessions set currency='NGN',capacity=9 where activity_id=aid;
  perform pg_temp.expect(not (public.get_experience_approval_readiness(aid,2)->'checks'->>'sessions')::boolean,'capacity above the reviewed group size blocks approval');
  update public.experience_sessions set capacity=8,timezone='UTC' where activity_id=aid;
  perform pg_temp.expect(not (public.get_experience_approval_readiness(aid,2)->'checks'->>'sessions')::boolean,'session timezone must match the reviewed activity');
  update public.experience_sessions set timezone='Africa/Lagos',ends_at=starts_at+interval '2 hours' where activity_id=aid;
  perform pg_temp.expect(not (public.get_experience_approval_readiness(aid,2)->'checks'->>'sessions')::boolean,'session duration must match the reviewed activity');
  update public.experience_sessions set ends_at=starts_at+interval '1 hour' where activity_id=aid;
  perform pg_temp.expect((public.get_experience_approval_readiness(aid,2)->>'can_approve')::boolean,'restoring current session terms restores readiness');
  perform pg_temp.expect(pg_temp.rejects(format('select public.approve_experience_activity(%L,1,%L)',aid,'Activity evidence, photos and dated sessions reviewed.')),'stale activity approval rejected');
  receipt:=public.approve_experience_activity(aid,2,'Activity evidence, photos and dated sessions reviewed.');
  perform pg_temp.expect(receipt->>'status'='approved' and (receipt->>'approved_from_revision')::integer=2 and (receipt->>'revision')::integer=3,'approval is bound to the reviewed application revision');
  perform pg_temp.expect(public.approve_experience_activity(aid,2,'Activity evidence, photos and dated sessions reviewed.')=receipt,'lost approval response replays the original result');
  perform pg_temp.expect((select count(*)=1 from public.experience_activity_events where activity_id=aid and action='approved'),'approval retry writes one decision event');
  perform pg_temp.expect(public.get_experience_activity(aid,true)->>'status'='approved','reviewer can reopen the approved record');
  perform pg_temp.expect(not exists(select 1 from jsonb_array_elements(public.get_experience_activity_review_queue()) row where row->>'id'=aid::text),'approved activity leaves the pending review queue');
  perform pg_temp.expect(exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=aid::text and e.event_type='experience.application.approved' and a.recipient_user_id=hid and a.workspace='worker'),'approval reaches host Activity');
  perform pg_temp.exercise_experience_publication(aid,review_session,h,c,s,hs,cs,ss,hid,cid,sid);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
  perform pg_temp.expect(not (public.get_experience_evidence_review(aid)->>'can_submit')::boolean,'approved evidence is read-only until revision');
  perform pg_temp.expect(pg_temp.rejects(format('select public.archive_my_experience_session(%L,%L,1)',aid,review_session)),'approved dated sessions cannot be changed silently');
  perform pg_temp.expect(pg_temp.rejects(format('select public.begin_experience_activity_photo(%L,%L,3,9,%L)',aid,gen_random_uuid(),'An unreviewed additional photo')),'approved photos require a new activity revision');
  receipt:=public.transition_my_experience_activity(aid,3,'withdraw');
  perform pg_temp.expect(receipt->>'status'='withdrawn','host can revise an approved activity');
  receipt:=public.transition_my_experience_activity(aid,4,'submit');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'session_id',cs,'role','authenticated')::text,true);
  receipt:=public.get_experience_approval_readiness(aid,5);
  perform pg_temp.expect(not (receipt->>'can_approve')::boolean and not (receipt->'checks'->>'sessions')::boolean,'resubmission cannot reuse obsolete session revisions for approval');
  raise exception using errcode='ZP001',message='Rollback approval branch only';
 exception when sqlstate 'ZP001' then null;
 end;
